const b = $input.first().json.body ?? $input.first().json;
const event = String(b.event || 'ping');
const chainUrl = String($env.GAIACHAIN_AUDIT_URL || '').trim();
let audit = { skipped: true, reason: 'GAIACHAIN_AUDIT_URL no configurada' };
if (chainUrl) {
  const r = await fetch(chainUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ event, ts: new Date().toISOString(), source: 'agri-brain-security' }),
  });
  const t = await r.text();
  let parsed;
  try { parsed = JSON.parse(t); } catch { parsed = { raw: t }; }
  audit = { http_status: r.status, response: parsed };
}
return [{ json: { success: true, event, audit, note: 'HoneyBadger/BFT solo si el endpoint expone consenso real.' } }];
